<?php
namespace App\Http\Controllers;
use App\Models\Pelanggan; use Illuminate\Http\Request;
class PelangganController extends Controller { public function index(Request $r){$q=$r->q; $pelanggans=Pelanggan::when($q,fn($x)=>$x->where('nama','like',"%$q%")->orWhere('no_hp','like',"%$q%"))->latest()->paginate(10);return view('pelanggans.index',compact('pelanggans','q'));} public function create(){return view('pelanggans.create');} public function store(Request $r){$d=$r->validate(['nama'=>'required','no_hp'=>'required','alamat'=>'nullable']);Pelanggan::create($d);return redirect()->route('pelanggan.index')->with('success','Pelanggan ditambahkan.');} public function edit(Pelanggan $pelanggan){return view('pelanggans.edit',compact('pelanggan'));} public function update(Request $r,Pelanggan $pelanggan){$d=$r->validate(['nama'=>'required','no_hp'=>'required','alamat'=>'nullable']);$pelanggan->update($d);return redirect()->route('pelanggan.index')->with('success','Data diperbarui.');} public function destroy(Pelanggan $pelanggan){$pelanggan->delete();return back()->with('success','Pelanggan dihapus.');}}
